96	        cwd: payloadCwd,
97	        projectConfigDirName: '.claude',
98	        ckignorePath: path.join(claudeDir, '.ckignore'),
99	        checkBroadPatterns: true
100	      }
101	    });
102	
103	    // Handle allowed commands
104	    if (result.isAllowedCommand) {
105	      timer.end({ tool: toolName, status: 'ok', exit: 0, note: 'allowed-command' });
106	      process.exit(0);
107	    }
108	
109	    // Handle broad pattern blocks
110	    if (result.blocked && result.isBroadPattern) {
111	      const errorMsg = formatBroadPatternError({
112	        blocked: true,
113	        reason: result.reason,
114	        suggestions: result.suggestions
115	      }, claudeDir);
116	      console.error(errorMsg);
117	      timer.end({
118	        tool: toolName,
119	        status: 'block',
120	        exit: 2,
121	        target: result.pattern || toolInput.path || toolInput.file_path || '',
122	        note: result.reason || 'broad-pattern'
123	      });
124	      process.exit(2);
125	    }
126	
127	    // Handle pattern blocks
128	    if (result.blocked) {
129	      const errorMsg = formatBlockedError({
130	        path: result.path,
131	        pattern: result.pattern,
132	        tool: toolName,
133	        claudeDir: claudeDir,
134	        configPath: result.configPath
135	      });
136	      console.error(errorMsg);
137	      timer.end({
138	        tool: toolName,
139	        status: 'block',
140	        exit: 2,
141	        target: result.path || '',
142	        note: result.pattern || 'blocked-path'
143	      });
144	      process.exit(2);
145	    }
146	
147	    // All paths allowed
148	    timer.end({ tool: toolName, status: 'ok', exit: 0 });
149	    process.exit(0);
150	
151	  } catch (error) {
152	    // Fail-open for unexpected errors
153	    console.error('WARN: Hook error, allowing operation -', error.message);
154	    logHookCrash('scout-block', error, { event: 'PreToolUse' });
155	    process.exit(0);
156	  }
157	} catch (e) {
