191	function checkScoutBlock({ toolName, toolInput, options = {} }) {
192	  const {
193	    ckignorePath,
194	    projectCkignorePath,
195	    claudeDir = path.join(process.cwd(), '.claude'),
196	    cwd = process.cwd(),
197	    projectConfigDirName,
198	    checkBroadPatterns = true
199	  } = options;
200	
201	  // Unwrap shell executor wrappers (bash -c "...", eval "...")
202	  // so the inner command gets properly analyzed
203	  if (toolInput.command) {
204	    const unwrapped = unwrapShellExecutor(toolInput.command);
205	    if (unwrapped !== toolInput.command) {
206	      toolInput = { ...toolInput, command: unwrapped };
207	    }
208	  }
209	
210	  // For Bash commands, split compound commands (&&, ||, ;) and check
211	  // each sub-command independently. This prevents "echo msg && npm run build"
212	  // from being blocked due to "build" token in the allowed build sub-command.
213	  // Must split BEFORE isAllowedCommand because BUILD_COMMAND_PATTERN has no end
214	  // anchor and would match the prefix of "npm run build && cat dist/file.js".
215	  if (toolInput.command) {
216	    const subCommands = splitCompoundCommand(toolInput.command);
217	    const nonAllowed = subCommands.filter(cmd => !isAllowedCommand(cmd.trim()));
218	    if (nonAllowed.length === 0) {
219	      return { blocked: false, isAllowedCommand: true };
220	    }
221	    // Only extract paths from non-allowed sub-commands
222	    if (nonAllowed.length < subCommands.length) {
223	      toolInput = { ...toolInput, command: nonAllowed.join(' ; ') };
224	    }
225	  }
226	
227	  // Check for overly broad glob patterns (Glob tool)
228	  if (checkBroadPatterns && (toolName === 'Glob' || toolInput.pattern)) {
229	    const broadResult = detectBroadPatternIssue(toolInput);
230	    if (broadResult.blocked) {
231	      return {
232	        blocked: true,
233	        isBroadPattern: true,
234	        pattern: toolInput.pattern,
235	        reason: broadResult.reason || 'Pattern too broad - may fill context with too many files',
236	        suggestions: broadResult.suggestions || []
237	      };
238	    }
239	  }
240	
241	  // Resolve .ckignore path
242	  const resolvedCkignorePath = ckignorePath || path.join(claudeDir, '.ckignore');
243	  const discoveredProjectCkignorePath = projectCkignorePath || findProjectCkignore(cwd, projectConfigDirName);
244	  const resolvedProjectCkignorePath = discoveredProjectCkignorePath
245	    && path.resolve(discoveredProjectCkignorePath) !== path.resolve(resolvedCkignorePath)
246	      ? discoveredProjectCkignorePath
247	      : null;
248	  const configPath = resolvedProjectCkignorePath || resolvedCkignorePath;
249	
250	  // Load patterns and create matcher
251	  const patterns = loadPatterns(resolvedCkignorePath, resolvedProjectCkignorePath);
252	  const matcher = createMatcher(patterns);
253	
254	  // Extract paths from tool input
255	  const extractedPaths = extractFromToolInput(toolInput);
256	
257	  // If no paths extracted, allow operation
258	  if (extractedPaths.length === 0) {
259	    return { blocked: false };
260	  }
261	
262	  // Check each path against patterns
263	  for (const extractedPath of extractedPaths) {
264	    const result = matchPath(matcher, extractedPath);
265	    if (result.blocked) {
266	      return {
267	        blocked: true,
268	        path: extractedPath,
269	        pattern: result.pattern,
270	        configPath,
271	        reason: `Path matches blocked pattern: ${result.pattern}`
272	      };
273	    }
274	  }
275	
276	  // All paths allowed
277	  return { blocked: false };
278	}
